def main():
    cases=[]
    for category,difficulty,source,vi,en in ROWS:
        doc=json.loads((ROOT/'data/curated/ready_documents'/f'{source}.json').read_text(encoding='utf8'))
        for language,query in [('vi',vi),('en',en)]:
            cases.append({'id':f'test_{len(cases)+1:03}', 'query':query, 'language':language,
                'cross_language':language=='vi','category':category,'difficulty':difficulty,
                'relevant_documents':[doc['source_url']],
                'label_basis':f"Draft judgment based on source topic and content: {doc['title']} ({source}.json); requires independent review."})
    # This question explicitly asks for both sources, independently of ranking.
    pair = ['medicines-painkillers', 'medicines-antibiotics']
    urls = [json.loads((ROOT/'data/curated/ready_documents'/f'{s}.json').read_text(encoding='utf8'))['source_url'] for s in pair]
    for language, query in [('vi','Thuốc giảm đau và kháng sinh khác nhau thế nào về mục đích sử dụng?'),
                            ('en','How do pain relievers and antibiotics differ in what they treat?')]:
        cases.append({'id':f'test_{len(cases)+1:03}', 'query':query, 'language':language,
                      'cross_language':language=='vi','category':'medication','difficulty':'medium',
                      'relevant_documents':urls,
                      'label_basis':'Draft judgment: question explicitly asks about both pain relievers and antibiotics; requires independent review.'})
    path=ROOT/'evaluation/rag_test_dataset.json'
    if path.exists(): raise SystemExit('Refusing to overwrite existing test dataset')
    path.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    print('Draft queries:',len(cases))
if __name__=='__main__':main()
